// nextFeedTime port: parity with web (golden values generated by running web's nextFeedTime on the
// same fixture), source identical to web, and frozen at lastFeed.timestamp (clock-independent).
import fs from 'fs';
import path from 'path';
import fx from './fixtures/snapshot-20261024.json';
import golden from './fixtures/nextFeed-web-golden.json';
import { deriveSettings, smoothedEffective } from '../calculations';
import { nextFeedTime, nextFeedAtLastFeed } from '../nextFeed';
import { frozenCalcSettings } from '../zoneSegments';
import { HistoryEntry } from '../settingsHistory';
import { Feed, Settings } from '../../types';

const feeds: Feed[] = fx.feeds;
const base = { weightKg: 6.2, yellowThresholdPct: 5, redThresholdPct: 10, timeFormat: '24h' as const };

test.each(golden.cases.map((c, i) => [i, c] as const))('case %i matches web output exactly', (_i, c) => {
  const fs_ = feeds.slice(0, c.n);
  const s = { ...base, mlPerKgPerDay: c.mlPerKgPerDay, preferredBottleWaterMl: c.pref } as Settings;
  const d = deriveSettings(s);
  const at = Math.max(...fs_.map(f => f.timestamp));
  const tot = smoothedEffective(fs_, d.hourlyRate, c.pref, at).totalMl;
  expect(nextFeedTime(fs_, d.hourlyRate, tot, d.dailyTargetMl, {
    maxCorrectionPct: c.maxCorrectionPct, useTargetAwarePredictor: c.useTargetAwarePredictor, nextBottleWaterMl: c.pref,
  })).toEqual(c.result);
});

const webSrc = path.resolve(__dirname, '../../../../baby-milk-tracker/src/lib/calculations.ts');
(fs.existsSync(webSrc) ? test : test.skip)('ported source is byte-identical to web (when the web repo is checked out alongside)', () => {
  const web = fs.readFileSync(webSrc, 'utf8');
  const start = web.indexOf('/**\n * Predictor 3 — Target-aware adjusted next bottle');
  const fnAt = web.indexOf('export function nextFeedTime(');
  const end = web.indexOf('\n}\n', fnAt) + 3;
  const mob = fs.readFileSync(path.resolve(__dirname, '../nextFeed.ts'), 'utf8');
  const port = mob.slice(mob.indexOf('// ── BEGIN PORT') , mob.indexOf('// ── END PORT')).split('\n').slice(1).join('\n');
  expect(port).toBe(web.slice(start, end));
});

describe('frozen at the last feed', () => {
  const last = Math.max(...feeds.map(f => f.timestamp));
  const iso = (ms: number) => new Date(ms).toISOString();
  const dayStart = new Date('2026-10-24T00:00:00+02:00').getTime();
  const weights = [{ timestamp: last - 86_400_000, weightKg: 6.2 }];
  const snap: HistoryEntry = { v: 1, kind: 'snapshot', effectiveFrom: iso(dayStart), changedAt: iso(dayStart), source: 'seed', appVersion: '1.1.58',
    changes: { mlPerKgPerDay: { new: 150 }, preferredBottleWaterMl: { new: 120 } } };
  const changeAt = last + 30 * 60_000;
  const change: HistoryEntry = { v: 1, kind: 'diff', effectiveFrom: iso(changeAt), changedAt: iso(changeAt), source: 'mobile', appVersion: '1.2.14',
    changes: { mlPerKgPerDay: { old: 150, new: 170 }, preferredBottleWaterMl: { old: 120, new: 150 } } };
  const before: Settings = { ...base, mlPerKgPerDay: 150, preferredBottleWaterMl: 120 };
  const live: Settings = { ...base, mlPerKgPerDay: 170, preferredBottleWaterMl: 150 };
  const opts = { maxCorrectionPct: 25, useTargetAwarePredictor: true };
  const run = (s: Settings, h: HistoryEntry[], w = weights) => nextFeedAtLastFeed(feeds, frozenCalcSettings(feeds, s, h, w, dayStart), opts);

  test('equals the web golden case for the settings in force at the last feed', () => {
    const g = golden.cases.find(c => c.mlPerKgPerDay === 150 && c.pref === 120 && c.n === feeds.length && c.maxCorrectionPct === 25 && c.useTargetAwarePredictor)!;
    expect(run(before, [snap])).toEqual(g.result);
  });
  test('settings changed and a weigh-in logged after the last feed do not move it', () => {
    const ref = run(before, [snap]);
    expect(run(live, [snap, change], [...weights, { timestamp: last + 3_600_000, weightKg: 7.5 }])).toEqual(ref);
  });
  test('does not read the clock', () => {
    const ref = run(before, [snap]);
    const spy = jest.spyOn(Date, 'now').mockReturnValue(last + 9 * 3_600_000);
    expect(run(before, [snap])).toEqual(ref);
    expect(spy).not.toHaveBeenCalled();
    spy.mockRestore();
  });
  test('no feeds → null', () => expect(nextFeedAtLastFeed([], frozenCalcSettings([], before, [snap], weights, dayStart), opts)).toBeNull());
});
